-- Clients organ -- generated by noctusai_lib.domain.clients.sql

SET search_path = nosnolimiar, public;

CREATE TABLE IF NOT EXISTS nosnolimiar.clients (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id               UUID NOT NULL,
    name                 TEXT NOT NULL CHECK (length(btrim(name)) > 0),
    phone                TEXT,
    email                TEXT,
    doc                  TEXT,
    birth_date           DATE,
    status               TEXT NOT NULL,
    tags                 TEXT[] NOT NULL DEFAULT '{}',
    notes                TEXT,
    lead_id              UUID,
    whatsapp_chat_id     TEXT,
    default_price_cents  BIGINT CHECK (default_price_cents IS NULL OR default_price_cents >= 0),
    session_duration_min INTEGER CHECK (session_duration_min IS NULL OR session_duration_min > 0),
    started_at           DATE NOT NULL DEFAULT CURRENT_DATE,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by           UUID
);
-- One client per lead: the guard that makes the lead -> client conversion idempotent (NULL lead_id never conflicts).
CREATE UNIQUE INDEX IF NOT EXISTS uq_clients_lead ON nosnolimiar.clients (org_id, lead_id);
CREATE INDEX IF NOT EXISTS idx_clients_name ON nosnolimiar.clients (org_id, name, id);
ALTER TABLE nosnolimiar.clients ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "clients_select_own_org" ON nosnolimiar.clients;
DROP POLICY IF EXISTS "service_role_bypass" ON nosnolimiar.clients;
CREATE POLICY "service_role_bypass" ON nosnolimiar.clients FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON nosnolimiar.clients FROM PUBLIC, anon, authenticated;
GRANT ALL ON nosnolimiar.clients TO service_role;

CREATE TABLE IF NOT EXISTS nosnolimiar.client_schedules (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id             UUID NOT NULL,
    client_id          UUID NOT NULL REFERENCES nosnolimiar.clients(id) ON DELETE CASCADE,
    weekday            SMALLINT NOT NULL CHECK (weekday BETWEEN 0 AND 6),
    slot_time          TIME NOT NULL,
    duration_min       INTEGER NOT NULL CHECK (duration_min > 0),
    price_cents        BIGINT CHECK (price_cents IS NULL OR price_cents >= 0),
    starts_on          DATE NOT NULL,
    ends_on            DATE CHECK (ends_on IS NULL OR ends_on >= starts_on),
    active             BOOLEAN NOT NULL DEFAULT true,
    materialized_until DATE,
    charge_absences    BOOLEAN NOT NULL DEFAULT true,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE nosnolimiar.client_schedules ADD COLUMN IF NOT EXISTS charge_absences BOOLEAN NOT NULL DEFAULT true;
CREATE INDEX IF NOT EXISTS idx_client_schedules_client ON nosnolimiar.client_schedules (org_id, client_id);
ALTER TABLE nosnolimiar.client_schedules ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "client_schedules_select_own_org" ON nosnolimiar.client_schedules;
CREATE POLICY "client_schedules_select_own_org" ON nosnolimiar.client_schedules FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('nosnolimiar')));
DROP POLICY IF EXISTS "service_role_bypass" ON nosnolimiar.client_schedules;
CREATE POLICY "service_role_bypass" ON nosnolimiar.client_schedules FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON nosnolimiar.client_schedules TO authenticated;
GRANT ALL ON nosnolimiar.client_schedules TO service_role;

CREATE TABLE IF NOT EXISTS nosnolimiar.client_sessions (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id        UUID NOT NULL,
    client_id     UUID NOT NULL REFERENCES nosnolimiar.clients(id) ON DELETE CASCADE,
    schedule_id   UUID REFERENCES nosnolimiar.client_schedules(id) ON DELETE SET NULL,
    starts_at     TIMESTAMPTZ NOT NULL,
    duration_min  INTEGER NOT NULL CHECK (duration_min > 0),
    status        TEXT NOT NULL,
    price_cents   BIGINT CHECK (price_cents IS NULL OR price_cents >= 0),
    waive_charge  BOOLEAN NOT NULL DEFAULT false,
    charge_absence BOOLEAN NOT NULL DEFAULT true,
    notes         TEXT,
    entry_id      UUID,
    booking_rev   INTEGER NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE nosnolimiar.client_sessions ADD COLUMN IF NOT EXISTS charge_absence BOOLEAN NOT NULL DEFAULT true;
-- One generated session per (schedule, instant): the guard that makes materialization idempotent.
CREATE UNIQUE INDEX IF NOT EXISTS uq_client_sessions_slot ON nosnolimiar.client_sessions (schedule_id, starts_at);
CREATE INDEX IF NOT EXISTS idx_client_sessions_org_starts ON nosnolimiar.client_sessions (org_id, starts_at, id);
CREATE INDEX IF NOT EXISTS idx_client_sessions_client_starts ON nosnolimiar.client_sessions (org_id, client_id, starts_at);
ALTER TABLE nosnolimiar.client_sessions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "client_sessions_select_own_org" ON nosnolimiar.client_sessions;
CREATE POLICY "client_sessions_select_own_org" ON nosnolimiar.client_sessions FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('nosnolimiar')));
DROP POLICY IF EXISTS "service_role_bypass" ON nosnolimiar.client_sessions;
CREATE POLICY "service_role_bypass" ON nosnolimiar.client_sessions FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON nosnolimiar.client_sessions TO authenticated;
GRANT ALL ON nosnolimiar.client_sessions TO service_role;

CREATE TABLE IF NOT EXISTS nosnolimiar.client_payments (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id         UUID NOT NULL,
    client_id      UUID NOT NULL REFERENCES nosnolimiar.clients(id) ON DELETE RESTRICT,
    amount_cents   BIGINT NOT NULL CHECK (amount_cents > 0),
    paid_on        DATE NOT NULL,
    account_id     UUID NOT NULL,
    method         TEXT NOT NULL,
    notes          TEXT,
    settlement_ids UUID[] NOT NULL DEFAULT '{}',
    created_by     UUID,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_client_payments_client ON nosnolimiar.client_payments (org_id, client_id, paid_on);
ALTER TABLE nosnolimiar.client_payments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "client_payments_select_own_org" ON nosnolimiar.client_payments;
CREATE POLICY "client_payments_select_own_org" ON nosnolimiar.client_payments FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('nosnolimiar')));
DROP POLICY IF EXISTS "service_role_bypass" ON nosnolimiar.client_payments;
CREATE POLICY "service_role_bypass" ON nosnolimiar.client_payments FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON nosnolimiar.client_payments TO authenticated;
GRANT ALL ON nosnolimiar.client_payments TO service_role;

-- The immutable intent log (EOA): who did what to which client / session / slot, when. Append-only: the service
-- role may only INSERT and SELECT. No FKs on purpose -- the history outlives a deleted session or slot. `data` never
-- carries free text (no administrative note, no clinical note): only ids, enums, amounts and dates.
CREATE TABLE IF NOT EXISTS nosnolimiar.client_events (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    client_id   UUID NOT NULL,
    session_id  UUID,
    schedule_id UUID,
    kind        TEXT NOT NULL,
    from_value  TEXT,
    to_value    TEXT,
    actor       UUID,
    data        JSONB NOT NULL DEFAULT '{}',
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_client_events_client ON nosnolimiar.client_events (org_id, client_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_client_events_session ON nosnolimiar.client_events (org_id, session_id, occurred_at);
ALTER TABLE nosnolimiar.client_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "client_events_select_own_org" ON nosnolimiar.client_events;
DROP POLICY IF EXISTS "service_role_bypass" ON nosnolimiar.client_events;
CREATE POLICY "service_role_bypass" ON nosnolimiar.client_events FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON nosnolimiar.client_events FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT ON nosnolimiar.client_events TO service_role;

-- The clinical note of a session (LGPD art. 11, sensitive health data): its own table, service role only (no
-- authenticated read path), read and written through admin-gated routes, never part of a list or an export.
CREATE TABLE IF NOT EXISTS nosnolimiar.client_session_notes (
    session_id UUID PRIMARY KEY REFERENCES nosnolimiar.client_sessions(id) ON DELETE CASCADE,
    org_id     UUID NOT NULL,
    body       TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by UUID
);
ALTER TABLE nosnolimiar.client_session_notes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "client_session_notes_select_own_org" ON nosnolimiar.client_session_notes;
DROP POLICY IF EXISTS "service_role_bypass" ON nosnolimiar.client_session_notes;
CREATE POLICY "service_role_bypass" ON nosnolimiar.client_session_notes FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON nosnolimiar.client_session_notes FROM PUBLIC, anon, authenticated;
GRANT ALL ON nosnolimiar.client_session_notes TO service_role;

-- Access tier of every table (KB § PATTERNS/security/access-tiers.md): the customer's own data, org-scoped.
COMMENT ON TABLE nosnolimiar.clients IS 'tier:org';
COMMENT ON TABLE nosnolimiar.client_schedules IS 'tier:org';
COMMENT ON TABLE nosnolimiar.client_sessions IS 'tier:org';
COMMENT ON TABLE nosnolimiar.client_payments IS 'tier:org';
COMMENT ON TABLE nosnolimiar.client_events IS 'tier:org';
COMMENT ON TABLE nosnolimiar.client_session_notes IS 'tier:org';
